#!/usr/bin/env bash
# Cargo RUSTC_WRAPPER for the consumer binary generated by trybuild. A dependency's
# cargo:rustc-link-arg applies to that package's targets, not the consumer.
set -eu
compiler=$1
shift
for arg in "$@"; do
    case "$arg" in
        */tests/compile_pass/abi_native_container_contracts.rs)
            case "$(uname -s)" in
                Darwin|Linux)
                    libdir="${LEAN_SYSROOT:?select the same Lean sysroot as the SDK}/lib/lean"
                    test -d "$libdir"
                    exec "$compiler" "$@" -C "link-arg=-Wl,-rpath,$libdir"
                    ;;
            esac
            ;;
    esac
done
exec "$compiler" "$@"
